<?php
namespace WPKit\SiteDoctor\Scanners; use WPKit\SiteDoctor\{SiteDoctorIssue,SiteDoctorScanner}; if(!defined('ABSPATH'))exit;
final class SecurityScanner implements SiteDoctorScanner{public function id():string{return 'security';}public function label():string{return 'Security';}public function scan():array{$o=[];if(!is_ssl())$o[]=$this->i('no-ssl','security','high','manual_only','HTTPS is not active','The current WordPress request is not using SSL.','Configure HTTPS at the hosting/CDN layer and verify WordPress URLs.');if(defined('WP_DEBUG')&&WP_DEBUG)$o[]=$this->i('debug-enabled','security','medium','manual_only','WP_DEBUG is enabled','Debug mode is enabled in the current environment.','Disable debugging on production after resolving development issues.');$plugins=get_plugins();$inactive=[];foreach($plugins as $file=>$p){if(!is_plugin_active($file))$inactive[]=$p['Name'];}if(count($inactive)>10)$o[]=$this->i('many-inactive-plugins','security','low','manual_only','Many inactive plugins detected','There are '.count($inactive).' inactive plugins.','Review and remove unused plugins after confirming they are not needed.');return $o;}private function i($id,$c,$s,$r,$t,$d,$rec){return new SiteDoctorIssue(['id'=>$id,'category'=>$c,'severity'=>$s,'risk'=>$r,'title'=>$t,'description'=>$d,'recommendation'=>$rec]);}}
